INSERT INTO users (id, email, name, is_staff, created_at) VALUES ('u-staff','you@example.com','MuzMesh',1,'2026-11-01T09:00:00.000Z'),('u-owner','owner@bookly.test','Demo Owner',0,'2026-11-01T09:00:00.000Z'),('u-editor','editor@bookly.test','Demo Editor',0,'2026-11-01T09:00:00.000Z'),('u-viewer','viewer@bookly.test','Demo Viewer',0,'2026-11-01T09:00:00.000Z');
INSERT INTO workspaces (id, slug, name, site_url, cms, cms_edit_url, monthly_minutes, monthly_posts, brand_config, created_at) VALUES ('w-bookly','bookly','Bookly','https://bookly.app/','sanity','https://bookly.sanity.studio/',120,8,'{"$schema": "../../tools/brand-kit/brand.config.schema.json", "name": "Bookly", "legalName": "Bookly Inc.", "prefix": "bk", "version": "v1 · Nov 2026", "url": "bookly.app", "email": "hello@bookly.app", "category": "an AI reading companion for busy professionals", "idea": {"headline": ["Read less.", "Remember more."], "promise": "Bookly turns the books you mean to read into ten-minute conversations you actually finish. The brand should feel like a good library: calm, warm, a little bookish, and never in a hurry.", "personality": "Warm, clear, quietly clever, never smug.", "pillars": [{"title": "Calm over clever", "body": "Lots of space, soft paper tones and one deep green. Nothing blinks, nothing shouts."}, {"title": "Books first", "body": "Real covers, real quotes, real page numbers. The product is about reading, so the brand looks like reading."}, {"title": "One serif, one sans", "body": "Fraunces for headlines gives the bookish warmth. Inter does all the work everywhere else."}, {"title": "Plain words", "body": "We explain like a well-read friend, not a productivity guru."}]}, "theme": {"default": "light"}, "colors": {"light": {"hex": "#FAF6EE", "name": "Linen", "use": "Page background. Warm, like paper."}, "dark": {"hex": "#14231C", "name": "Forest", "use": "Dark sections, the app''s night mode, social posts."}, "textOnLight": {"hex": "#1E2420", "name": "Ink", "use": "Text on linen."}, "textOnDark": {"hex": "#F3EFE6", "name": "Page", "use": "Text on forest."}, "accent": {"hex": "#1F7A55", "name": "Bookly green", "use": "The one action per view, links, highlights."}, "support": [{"hex": "#E8B44C", "name": "Bookmark", "use": "Small highlights only: a ribbon, a streak badge. Never text on linen."}, {"hex": "#C8603F", "name": "Spine", "use": "Illustrations and book covers only."}]}, "fonts": {"display": {"family": "Fraunces", "weights": [500, 600], "italic": true, "fallback": "Georgia, serif", "tracking": "-0.02em"}, "body": {"family": "Inter", "weights": [400, 500, 600], "fallback": "system-ui, sans-serif"}, "label": {"family": "Inter", "style": "caps", "weight": 600, "tracking": "0.08em"}}, "shape": {"radius": "soft", "buttons": "rounded"}, "labelMarker": "dot", "logo": {"wordmark": {"text": "bookly", "font": "display", "weight": 600, "tracking": "-0.03em"}, "files": {}}, "voice": {"headline": ["Like a friend", "who reads a lot."], "summary": "We sound like a well-read friend: warm, specific, a little playful, never preachy about productivity.", "use": ["read", "finish", "remember", "chapter", "your shelf"], "avoid": ["hack", "10x", "grind", "unlock", "revolutionary", "AI-powered", "game-changer", "seamless"], "write": ["Finish the book you started in March.", "Ten minutes a day. One chapter at a time.", "We read the boring bits so you don''t have to."], "not": ["Unlock 10x knowledge with AI-powered reading hacks 🚀", "The ultimate productivity tool for high performers.", "Read 100 books a year!"], "ctaPrimary": "Start reading", "ctaSecondary": "See a sample", "names": "Bookly in text, bookly (lowercase) in the logo, Bookly Inc. for legal."}, "imagery": {"headline": ["Real books,", "real light."], "summary": "Real books, real hands, real reading corners. Warm daylight, linen and wood. Never stock ''success'' photos or glowing brains.", "do": ["Books on tables, in hands, on trains.", "Warm natural light, muted colour.", "Close crops of pages and margins."], "dont": ["AI-generated people or robots.", "Neon, gradients, glowing brains.", "Stacks of money, trophies, mountain summits."], "style": "Documentary photograph, calm and unhurried. Warm daylight from a window, linen, paper and wood tones, a little deep green, muted colour, soft contrast, shallow depth of field, 50mm lens, fine film grain. Leave quiet space on one side for a headline.", "avoid": "text, letters, logos, watermarks, readable book titles or screens, robots, glowing brains, neon, gradients, 3D renders, stacks of money, trophies, mountain summits, posed stock smiles, extra fingers", "prompts": [{"title": "Reading corner", "ar": "4:5", "use": "Hero and app store images", "subject": "A person in their thirties reading a paperback in a deep armchair by a window, legs tucked up, a mug of tea on the side table, late afternoon light"}, {"title": "Commute chapter", "ar": "4:5", "use": "Social posts about reading in ten minutes", "subject": "A commuter reading a phone held low on a quiet morning train, a paperback poking out of their bag, soft light through the window, other passengers blurred"}, {"title": "Margins", "ar": "1:1", "use": "Quote posts and carousel covers", "subject": "Close-up of an open book with pencil underlines and a small handwritten note in the margin, a green ribbon bookmark across the page"}, {"title": "The shelf", "ar": "16:9", "use": "Website section backgrounds, newsletter headers", "subject": "A wooden bookshelf at home with books lying at different angles, a small plant, a reading lamp switched on, most of the frame calm and uncluttered"}, {"title": "Bedside", "ar": "9:16", "use": "Story backgrounds with text on top", "subject": "A bedside table at night with a closed book, reading glasses and a small warm lamp, the rest of the room in soft darkness"}, {"title": "Desk notes", "ar": "3:2", "use": "Blog headers about remembering what you read", "subject": "Top-down view of a linen-covered desk with an open notebook of short handwritten summaries, a pen and a cup of coffee, generous empty space"}], "after": ["Keep the natural grade: warm, muted, no filters or heavy presets.", "Check hands, faces and pages at 100%. Reject warped fingers, fake lettering and plastic skin.", "Crop so the subject sits on one third and the quiet space holds the headline."], "rules": ["Generated images are for mood, backgrounds and editorial scenes.", "Never present a generated person as a real customer, author, team member or testimonial.", "Never generate the logo, real book covers or app screens. Add those afterwards in the layout."]}}','2026-11-01T09:00:00.000Z');
